<script lang="ts">
	// @ts-expect-error — generated by Wails
	import { GetDisks, GetDiskPartitions } from '@wails/go/gui/App.js';
	// @ts-expect-error — generated by Wails
	import { LogInfo as WailsLogInfo, LogError as WailsLogError } from '@wails/runtime/runtime';

	// Safe logging wrapper - works in both Wails and dev mode
	function logInfo(msg: string): void {
		try { WailsLogInfo(msg); } catch { /* dev mode: no Wails runtime */ }
	}
	import PageLayout from '$components/PageLayout.svelte';
	import Button from '$components/Button.svelte';
	import { diskSelectionData, pageValid } from '$lib/state.svelte';
	import type { DiskInfo, PartitionDetail } from '$lib/types';
	import { formatSize, FILESYSTEMS } from '$lib/types';


	let disks = $state<DiskInfo[]>([]);
	let selectedDiskId = $state<string>('');
	let partitions = $state<PartitionDetail[]>([]);
	let partitionsLoading = $state(false);
	let loading = $state(true);
	let error = $state<string | null>(null);

	async function loadDisks(): Promise<void> {
		try {
			disks = (await GetDisks()) ?? [];
			if (disks.length === 0) {
				error = null;
			}
		} catch (err) {
			error = `Failed to load disks: ${err instanceof Error ? err.message : String(err)}`;
			try { WailsLogError(`[DiskSelectionPage] ${error}`); } catch { /* dev mode */ }
		} finally {
			loading = false;
		}
	}

	async function selectDisk(disk: DiskInfo): Promise<void> {
		selectedDiskId = disk.path;
		diskSelectionData.diskId = disk.path;
		diskSelectionData.disk = disk;
		logInfo(`[DiskSelectionPage] Selected: ${disk.path} (${formatSize(disk.size)})`);

		// Load partition details for the selected disk
		partitionsLoading = true;
		partitions = [];
		try {
			const parts = await GetDiskPartitions(disk.path);
			partitions = parts ?? [];
		} catch (err) {
			logInfo(`[DiskSelectionPage] Failed to load partitions: ${err}`);
		} finally {
			partitionsLoading = false;
		}
	}

	loadDisks();

	// Update pageValid based on selection
	$effect(() => {
		pageValid.value = !!diskSelectionData.diskId && !!diskSelectionData.fileSystem;
	});

	// Sync to store when requested (before validation)
	$effect(() => {
		const handler = () => {
			const disk = disks.find(d => d.path === selectedDiskId) ?? null;
			diskSelectionData.diskId = selectedDiskId;
			diskSelectionData.disk = disk;
			logInfo(`[DiskSelectionPage] Syncing to store for validation`);
		};
		document.addEventListener('sync-to-store', handler);
		return () => document.removeEventListener('sync-to-store', handler);
	});
</script>
<PageLayout title="Select Installation Disk">
		<p class="hint">Choose a disk to install AestheticOS. All data on the selected disk will be erased.</p>

		{#if loading}
		<div class="loading-state">
			<p class="loading-text">Scanning for disks...</p>
		</div>
	{:else if error}
		<div class="error-state">
			<p class="error-text">{error}</p>
			<Button variant="secondary" onClick={loadDisks}>Retry</Button>
		</div>
	{:else if disks.length === 0}
		<div class="empty-state">
			<p class="empty-text">No storage devices found.</p>
		</div>
	{:else}
		<!-- FS selector (pinned) and disk list (scrollable) -->
		<div class="disk-page-content">
			<!-- Filesystem selector (pinned) -->
			<div class="fs-section">
			<h3 class="fs-title">Root Filesystem</h3>
			<p class="fs-hint">Choose the filesystem for the root partition. This cannot be changed after installation.</p>
			<div class="fs-options">
				{#each FILESYSTEMS as fs}
					<button
						type="button"
						class={['fs-option', { selected: diskSelectionData.fileSystem === fs }]}
						onclick={() => { diskSelectionData.fileSystem = fs; }}
					>
						<div class="fs-option-main">
							<div class="fs-radio">
								<div class={['radio-dot', { checked: diskSelectionData.fileSystem === fs }]}>
									{#if diskSelectionData.fileSystem === fs}
										<span class="radio-dot-inner"></span>
									{/if}
								</div>
							</div>
							<span class="fs-name">{fs}</span>
						</div>
						<span class="fs-desc">{fs === 'ext4' ? 'Traditional, stable, mature. Excellent compatibility.' : 'Modern, advanced features. Copy-on-write, snapshots, compression.'}</span>
					</button>
				{/each}
			</div>
		</div>

		<!-- Disk list (scrollable) -->
		<div class="disk-list">
			{#each disks as disk (disk.path)}
				<button
					type="button"
					class={['disk-card', { selected: selectedDiskId === disk.path }]}
					onclick={() => selectDisk(disk)}
				>
					<div class="disk-main">
						<div class="disk-icon">
							{#if disk.rotational}
								<span class="icon-hdd" title="Hard Disk Drive">💾</span>
							{:else}
								<span class="icon-ssd" title="Solid State Drive">⚡</span>
							{/if}
						</div>
						<div class="disk-info">
							<div class="disk-name">{disk.model}</div>
							<div class="disk-details">
								<span class="disk-size">{formatSize(disk.size)}</span>
								<span class="disk-divider">·</span>
								<span class="disk-type">{disk.rotational ? 'HDD' : 'SSD'}</span>
								{#if disk.trans}
									<span class="disk-divider">·</span>
									<span class="disk-trans">{disk.trans.toUpperCase()}</span>
								{/if}
							</div>
						</div>
						<div class="disk-radio">
							<div class={['radio', { checked: selectedDiskId === disk.path }]}>
								{#if selectedDiskId === disk.path}
									<span class="radio-dot"></span>
								{/if}
							</div>
						</div>
					</div>

					{#if disk.fstype}
						<div class="disk-extra">
							<span class="tag fstype-tag">Existing: {disk.fstype}</span>
						</div>
					{/if}
					{#if disk.mountpoint}
						<div class="disk-extra">
							<span class="tag mount-tag">Mounted: {disk.mountpoint}</span>
						</div>
					{/if}
					{#if disk.serial}
						<div class="disk-extra">
							<span class="tag serial-tag">S/N: {disk.serial}</span>
						</div>
					{/if}

					<!-- Partition details for selected disk -->
					{#if selectedDiskId === disk.path}
						<div class="partition-section">
							{#if partitionsLoading}
								<p class="partition-loading">Scanning partitions...</p>
						 {:else if partitions.length > 0}
								<div class="partition-list">
									{#each partitions as part (part.path)}
										<div class="partition-row">
											<div class="partition-name">{part.name}</div>
											<div class="partition-details">
												{#if part.fstype}
													<span class="partition-tag fstype">{part.fstype}</span>
												{/if}
												<span>{formatSize(part.size)}</span>
												{#if part.mountpoint}
													<span class="partition-tag mounted">Mounted: {part.mountpoint}</span>
												{/if}
											</div>
										</div>
									{/each}
								</div>
							{:else}
								<p class="partition-empty">No partitions found on this disk.</p>
							{/if}
						</div>
					{/if}
				</button>
			{/each}
		</div>
		</div>
	{/if}
</PageLayout>

